#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
auto kadane=[&](bool mx){long long best=a[0],cur=a[0];
for(int i=1;i<n;++i){
if(mx)cur=max(a[i],cur+a[i]);else cur=min(a[i],cur+a[i]);
if(mx)best=max(best,cur);else best=min(best,cur);}
return best;};
long long total=0;for(long long x:a)total+=x;
long long mx=kadane(true),mn=kadane(false);
long long ans=mx;
if(total-mn!=0)ans=max(ans,total-mn);
bool allNeg=true;for(long long x:a)if(x>=0)allNeg=false;
if(allNeg)ans=mx;
printf("%lld\n",ans);return 0;}

